public class MyMentionProvider : INotionMentionProvider
{
    private static readonly List<MentionUser> Users =
    [
        new() { Id = "u1", DisplayName = "Alice Novak",  Email = "alice@example.com" },
        new() { Id = "u2", DisplayName = "Bob Kral",     Email = "bob@example.com" },
    ];

    private readonly INotionDataProvider _data;
    public MyMentionProvider(INotionDataProvider data) => _data = data;

    public Task<IEnumerable<IMentionUser>> SearchUsersAsync(string query)
    {
        IEnumerable<IMentionUser> result = Users;
        if (!string.IsNullOrWhiteSpace(query))
            result = result.Where(u => u.DisplayName.Contains(query, StringComparison.OrdinalIgnoreCase));
        return Task.FromResult(result);
    }

    public Task<IEnumerable<INotionPage>> SearchPagesAsync(string query)
        => _data.GetChildPagesAsync(null)
               .ContinueWith(t => t.Result.Where(p =>
                   p.Title.Contains(query, StringComparison.OrdinalIgnoreCase)));
}
